/** Scatter marker centres and the plot rectangle (probe runs): SVG circle paths, or Canvas arc() calls. */
export function circleCenters(d) {
  const out = [];
  const re = /M\s*(-?[\d.]+(?:e[-+]?\d+)?)[\s,]+(-?[\d.]+(?:e[-+]?\d+)?)\s*A\s*(-?[\d.]+)/g;
  let m;
