/**
 * `createChart`: the browser host of the controller (controller.ts). It resolves the target, builds the
 * figure, the mark and text renderers and the interaction layer, and connects the page's observers to the
 * controller. Every setup step registers its own cleanup as soon as it succeeded, so a failure part-way
 * through creation, or `destroy()`, leaves the target as it was (including the custom properties the theme
 * wrote on it).
 *
 * Document-level listeners (theme and environment watchers, the interaction layer's keyboard and pointer
 * listeners on the document) are released when the target leaves the document without `destroy()`, so a
 * forgotten chart does not stay reachable from the page, and are attached again if the target comes back.
 * Detachment is noticed by the observers the chart already has (the resize observer reports a zero box),
 * not by polling.
 */
import { svgRendererWith } from '../render/svg';
import { createTextLayer, type TextLayer } from '../render/text';
import { ensureStyles, resolveTheme, watchTheme } from '../theme';
import { createFigure, type Figure } from '../dom/figure';
import { createInteraction, type Interaction } from '../dom/interaction';
import { mappingOf } from '../dom/mapping';
import type { DeliveryConsole } from './delivery';
import { createMeasurer, noteFontLoad, readTextStyle, resolveLocale, viewerTimeZone, watchEnvironment, watchLanguage } from './environment';
import { controllerFor, type ChartHandle, type Controller, type ControllerActions } from './controller';
import type { Composition } from './composition';

export type { BenchHook, ChartHandle, ChartKind, DevHook, Stage } from './controller';

export interface ChartEnvironmentOverrides {
  readonly console?: DeliveryConsole | null;
}

/** Suffixes of the ids a chart gives its elements (figure, interaction, table). */
const ID_SUFFIXES = ['', '-t', '-st', '-s', '-m', '-n', '-i', '-proxy', '-table', '-table-caption', '-table-jump', '-table-jump-error'];
let instances = 0;

/** An id prefix none of whose element ids exist in the page yet (spec A1: ids unique per chart). */
function allocateId(doc: Document): string {
  for (;;) {
    const id = `axylo-${++instances}`;
    if (ID_SUFFIXES.every(suffix => doc.getElementById(id + suffix) === null)) return id;
  }
}

export function createChart(composition: Composition, target: unknown, input: unknown, overrides: ChartEnvironmentOverrides = {}): ChartHandle {
  const root = resolveTarget(target);
  const doc = root.ownerDocument;
  const win = doc.defaultView;
  if (win === null) throw new Error('Axylo: the target element is not in a document with a window.');

  // Cleanup in reverse order of setup; each step adds its own once it succeeded.
  const cleanup: (() => void)[] = [];
  const release = (): void => {
    for (let fn = cleanup.pop(); fn; fn = cleanup.pop()) {
      try {
        fn();
      } catch {
        // Keep releasing the rest.
      }
    }
  };

  let controller: Controller | null = null;
  try {
    const id = allocateId(doc);

    const renderer = svgRendererWith(composition.svg, doc);
    cleanup.push(() => renderer.destroy());
    const textLayer: TextLayer = createTextLayer(doc);
    cleanup.push(() => textLayer.destroy());
    const figure: Figure = createFigure(root, id, { marks: renderer.element, text: textLayer.element });
    cleanup.push(() => figure.destroy());

    // The interaction layer is built before the controller that answers it, so its actions forward late.
    const actions: ControllerActions = {
      zoom: w => controller?.actions.zoom(w),
      toggle: k => controller?.actions.toggle(k),
      pause: p => controller?.actions.pause(p),
      select: r => controller?.actions.select(r),
      hover: r => controller?.actions.hover(r),
    };
    const interaction: Interaction = createInteraction(composition.interaction, figure, renderer, actions);
    cleanup.push(() => interaction.destroy());
    const measurer = createMeasurer(doc);
    ensureStyles(doc);

    // Watchers that the document holds; released while the target is out of the document.
    let watching: (() => void) | null = null;
    let watchedBefore = false;
    const watch = (): void => {
      if (watching || controller === null) return;
      const c = controller;
      if (watchedBefore) {
        // Back in the document: fonts may have changed while it was out, and measurements made with the old
        // ones must not be reused (final review, finding 14).
        noteFontLoad(doc);
        c.invalidate.page();
      }
      watchedBefore = true;
      // Each watcher's release is registered as soon as it exists, so one that fails part-way leaves no
      // other behind (final review, finding 14).
      const stops: (() => void)[] = [];
      watching = () => {
        for (let stop = stops.pop(); stop; stop = stops.pop()) {
          try { stop(); } catch { /* keep releasing */ }
        }
      };
      try {
        stops.push(watchTheme(root, () => c.invalidate.theme()));
        stops.push(watchEnvironment(win, {
          pixelRatio: () => c.invalidate.pixelRatio(),
          motion() {
            // Nothing is animated yet (spec I5), so there is nothing to change.
          },
          fonts() {
            noteFontLoad(doc);
            c.invalidate.fonts();
          },
        }));
        stops.push(watchLanguage(root, () => c.invalidate.language()));
        interaction.attach();
        stops.push(() => interaction.detach());
      } catch (error) {
        // This attempt's subscriptions are released and the chart is not watching: the next resize
        // notification tries again, instead of finding `watching` set and skipping setup (verification,
        // defect 11).
        unwatch();
        throw error;
      }
    };
    const unwatch = (): void => {
      watching?.();
      watching = null;
    };
    cleanup.push(unwatch);

    // A font can arrive without a 'loadingdone' (a FontFace loaded first and then added to document.fonts):
    // a probe set like the labels changes size whenever their font does, and that is a font load (L1).
    const fontProbe = doc.createElement('div');
    fontProbe.className = 'axylo-font-probe';
    textLayer.element.appendChild(fontProbe);
    let probeSize: string | null = null;
    const fontObserver = new win.ResizeObserver(() => {
      const box = fontProbe.getBoundingClientRect();
      const size = `${box.width}x${box.height}`;
      if (probeSize !== null && size !== probeSize && controller !== null && root.isConnected) {
        noteFontLoad(doc);
        controller.invalidate.fonts();
      }
      probeSize = size;
    });
    fontObserver.observe(fontProbe);
    cleanup.push(() => fontObserver.disconnect());

    const resizeObserver = new win.ResizeObserver(() => {
      if (controller === null) return;
      // A target taken out of the document reports a zero box: let go of the document until it returns.
      if (!root.isConnected) {
        unwatch();
        return;
      }
      watch();
      controller.invalidate.resize();
    });
    cleanup.push(() => resizeObserver.disconnect());

    controller = controllerFor(composition, input, {
      id,
      // The author's own id names an untitled chart in diagnostics; the allocated one stays for the DOM.
      targetId: root.id || null,
      console: overrides.console === undefined ? (win.console as DeliveryConsole) : overrides.console,
      page: doc,
      get timeZone() { return viewerTimeZone(); },
      renderer,
      text: textLayer,
      figure,
      interaction,
      measurer,
      requestFrame: callback => win.requestAnimationFrame(callback),
      cancelFrame: handle => win.cancelAnimationFrame(handle),
      locale: option => resolveLocale(option, doc),
      pageLang() {
        const lang = root.closest('[lang]')?.getAttribute('lang')?.trim();
        return lang ? lang : null;
      },
      labelText(own) {
        const el = doc.getElementById(own);
        return el === null ? null : el.textContent ?? '';
      },
      textStyle: () => readTextStyle(textLayer.element),
      measure() {
        if (!root.isConnected) return null;
        const box = figure.figure.getBoundingClientRect();
        if (box.width <= 0 && box.height <= 0) return null;
        const plot = figure.plot.getBoundingClientRect();
        // Layout pixels, which the marks, the text and picking use: a CSS transform on an ancestor scales the
        // bounding rect, not the layout. The scale is the interaction layer's own mapping (decision 0004
        // revision 3, rule 10): bounding rect over the fractional computed size, exactly 1 only within the
        // computed size's serialization (1e-5), so a scale of 1.015 or 0.99 is not taken for 1 (it laid the
        // scene out 9 px too wide on a 600 px plot), and an unscaled sub-pixel width stays exactly 1.
        const mapping = mappingOf(figure.plot);
        const sx = mapping.kx;
        const sy = mapping.ky;
        // When the plot is squeezed to nothing, how far the rest overflows the figure is how much room is
        // missing; that keeps the L8 decision continuous below zero.
        const overflow = plot.height < 1 ? Math.max(0, figure.figure.scrollHeight - figure.figure.clientHeight) : 0;
        const stage = figure.stage.getBoundingClientRect();
        return { width: plot.width / sx, height: plot.height / sy - overflow, room: { width: stage.width / sx, height: stage.height / sy } };
      },
      stripHeight() {
        // The strip as the stylesheet would reserve it, in this figure's own font: a hidden copy is measured
        // (decision 0004 rule 5: two line heights of the strip's own text, whatever the page's size).
        const holder = doc.createElement('div');
        holder.className = 'axylo-readout-mode';
        holder.style.cssText = 'position: absolute; left: 0; top: 0; width: 100px; visibility: hidden; pointer-events: none;';
        const strip = doc.createElement('div');
        strip.className = 'axylo-readout';
        holder.appendChild(strip);
        figure.figure.appendChild(holder);
        const height = parseFloat(win.getComputedStyle(strip).height);
        holder.remove();
        return Number.isFinite(height) ? height : NaN;
      },
      devicePixelRatio: () => win.devicePixelRatio || 1,
      // Scoped to this chart's own figure: properties and the scheme go with it (finding 10).
      theme: (keys, colors) => resolveTheme(figure.figure, keys, colors),
      surfaces(visible) {
        // Hidden without drawing: the error revision does not depend on the methods that may have failed.
        for (const el of [renderer.element, textLayer.element]) el.style.visibility = visible ? '' : 'hidden';
      },
      dispose: release,
    });
    resizeObserver.observe(figure.plot);
    resizeObserver.observe(figure.figure);
    if (root.isConnected) watch();
    return controller.handle;
  } catch (error) {
    // A rejected strict create, or a failure part-way through: nothing stays behind, a controller that was
    // already created (its first frame queued) included (review 3, finding 9).
    const created = controller as Controller | null;
    controller = null;
    try { created?.handle.destroy(); } catch { /* releasing the rest matters more */ }
    release();
    throw error;
  }
}

function resolveTarget(target: unknown): HTMLElement {
  if (typeof target === 'string') {
    const doc = (globalThis as { document?: Document }).document;
    if (!doc) throw new Error(`Axylo: no document to find the target ${JSON.stringify(target)} in.`);
    let found: Element | null = null;
    try {
      found = doc.querySelector(target);
    } catch {
      throw new Error(`Axylo: the target selector ${JSON.stringify(target)} is not a valid CSS selector.`);
    }
    if (!found) throw new Error(`Axylo: the target selector ${JSON.stringify(target)} matches no element.`);
    return found as HTMLElement;
  }
  if (target !== null && typeof target === 'object' && (target as Node).nodeType === 1) return target as HTMLElement;
  throw new Error('Axylo: the target must be a CSS selector or an element.');
}
/**
 * The browser inputs that output depends on besides options and data (contracts: Environment), and the
 * watchers that say when one of them changed: device pixel ratio, reduced motion, web fonts finishing a load.
 * Nothing here runs at import time; every function takes the window or element it reads.
 */
import type { TextMeasurer, TextStyle } from './contracts';

export function viewerTimeZone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
  } catch {
    return 'UTC';
  }
}

/** `options.locale`, else the document language, else the browser's, as a locale Intl accepts. */
export function resolveLocale(option: unknown, doc: Document | null): string {
  const candidates = [option, doc?.documentElement.lang, doc?.defaultView?.navigator.language];
  for (const candidate of candidates) {
    if (typeof candidate !== 'string' || candidate.trim() === '') continue;
    try {
      const [canonical] = Intl.getCanonicalLocales(candidate.trim());
      if (canonical) return canonical;
    } catch {
      // Not a locale tag; try the next source.
    }
  }
  return new Intl.NumberFormat().resolvedOptions().locale;
}

function pixels(value: string, fontSize: number): number {
  if (value === '' || value === 'normal') return NaN;
  const n = parseFloat(value);
  if (!Number.isFinite(n)) return NaN;
  return value.endsWith('px') ? n : n * fontSize;
}

/**
 * The text style of tick labels, read from the text layer's own computed style, so measurement agrees with
 * what the layer renders (it uses `font-size: max(12px, 1em)`), including the page's text spacing (spec A6).
 */
export function readTextStyle(element: Element): TextStyle {
  const win = element.ownerDocument.defaultView;
  const style = win?.getComputedStyle(element);
  const fontSize = style ? parseFloat(style.fontSize) || 12 : 12;
  if (!style) return { font: `${fontSize}px sans-serif`, letterSpacing: 0, wordSpacing: 0, lineHeight: fontSize * 1.2 };
  const family = style.fontFamily || 'sans-serif';
  const font = `${style.fontStyle || 'normal'} ${style.fontWeight || '400'} ${fontSize}px ${family}`;
  const letterSpacing = pixels(style.letterSpacing, fontSize);
  const wordSpacing = pixels(style.wordSpacing, fontSize);
  const lineHeight = pixels(style.lineHeight, fontSize);
  return {
    font,
    letterSpacing: Number.isFinite(letterSpacing) ? letterSpacing : 0,
    wordSpacing: Number.isFinite(wordSpacing) ? wordSpacing : 0,
    // 'normal' depends on the font's metrics; 1.2 is the common value and errs on the side of room.
    lineHeight: Number.isFinite(lineHeight) ? lineHeight : Math.ceil(fontSize * 1.2),
  };
}

const contexts = new WeakMap<Document, CanvasRenderingContext2D | null>();
/** Measured widths per document, for every style together, so the bound holds for the whole page. */
const caches = new WeakMap<Document, Map<string, number>>();
const fontEpochs = new WeakMap<Document, number>();
/** The font epoch each document's context last resolved its font in. */
const contextEpochs = new WeakMap<Document, number>();
export const MEASUREMENT_CACHE_LIMIT = 8192;

/**
 * Web fonts finished loading in `doc`: widths measured with a fallback font are wrong now. Every chart of
 * the document calls this on the same event; the first clears the cache and the epoch moves on.
 */
export function noteFontLoad(doc: Document): void {
  fontEpochs.set(doc, (fontEpochs.get(doc) ?? 0) + 1);
  caches.get(doc)?.clear();
}

/** How many widths the document's cache holds (for tests of its bound). */
export function measurementCacheSize(doc: Document): number {
  return caches.get(doc)?.size ?? 0;
}

type SpacingContext = CanvasRenderingContext2D & { letterSpacing?: string; wordSpacing?: string };

/**
 * Canvas `measureText` with the computed font and the page's letter and word spacing (spec A6). Where the
 * context supports `letterSpacing` and `wordSpacing` they are set on it, so the browser adds them as it
 * does for the text layer; otherwise they are added the way CSS adds them (after every character, and
 * after every space). Cached per document, font epoch, style and string.
 */
export function createMeasurer(doc: Document): TextMeasurer {
  return {
    width(text: string, style: TextStyle): number {
      let ctx = contexts.get(doc);
      if (ctx === undefined) {
        ctx = doc.createElement('canvas').getContext('2d');
        contexts.set(doc, ctx);
      }
      let cache = caches.get(doc);
      if (!cache) caches.set(doc, cache = new Map());
      const key = `${fontEpochs.get(doc) ?? 0}|${style.font}|${style.letterSpacing}|${style.wordSpacing}|${text}`;
      const hit = cache.get(key);
      if (hit !== undefined) return hit;
      let width: number;
      let spaced = false;
      if (ctx) {
        const c = ctx as SpacingContext;
        const epoch = fontEpochs.get(doc) ?? 0;
        if (contextEpochs.get(doc) !== epoch) {
          // WebKit keeps the font it resolved when `font` was assigned and does not resolve it again when the
          // same string is assigned: after a font load, a different font is assigned first, so the wanted one
          // is resolved anew (the engines report, WebKit section). Once per load; Chrome and Firefox measure the
          // same either way.
          c.font = c.font === '10px serif' ? '10px sans-serif' : '10px serif';
          contextEpochs.set(doc, epoch);
        }
        if (c.font !== style.font) c.font = style.font;
        if (typeof c.letterSpacing === 'string' && typeof c.wordSpacing === 'string') {
          const letter = `${style.letterSpacing}px`;
          const word = `${style.wordSpacing}px`;
          if (c.letterSpacing !== letter) c.letterSpacing = letter;
          if (c.wordSpacing !== word) c.wordSpacing = word;
          spaced = true;
        }
        width = c.measureText(text).width;
      } else {
        width = text.length * parseFloat(/(\d+(?:\.\d+)?)px/.exec(style.font)?.[1] ?? '12') * 0.6;
      }
      if (!spaced) {
        if (style.letterSpacing !== 0) width += style.letterSpacing * [...text].length;
        if (style.wordSpacing !== 0) {
          let spaces = 0;
          for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) === 32) spaces++;
          width += style.wordSpacing * spaces;
        }
      }
      if (cache.size >= MEASUREMENT_CACHE_LIMIT) cache.clear();
      cache.set(key, width);
      return width;
    },
  };
}

export function sameTextStyle(a: TextStyle | null, b: TextStyle): boolean {
  return a !== null && a.font === b.font && a.letterSpacing === b.letterSpacing &&
    a.wordSpacing === b.wordSpacing && a.lineHeight === b.lineHeight;
}

/**
 * Calls `onChange` when the device pixel ratio changes (browser zoom, moving to another screen), when
 * reduced motion is toggled, and when web fonts finish loading. Returns `stop`.
 */
export function watchEnvironment(win: Window, handlers: { pixelRatio(): void; motion(): void; fonts(): void }): () => void {
  let stopped = false;
  // Each subscription registers its removal as soon as it exists, so a failure part-way (a matchMedia that
  // throws) leaves none behind (review 3, finding 9).
  const undo: (() => void)[] = [];
  const stop = (): void => {
    stopped = true;
    for (let fn = undo.pop(); fn; fn = undo.pop()) {
      try { fn(); } catch { /* keep releasing */ }
    }
  };
  try {
    let ratioQuery: MediaQueryList | null = null;
    const onRatio = (): void => {
      if (stopped) return;
      arm();
      handlers.pixelRatio();
    };
    // A resolution query matches one ratio only, so it is re-armed for the new ratio after each change.
    const arm = (): void => {
      ratioQuery?.removeEventListener('change', onRatio);
      ratioQuery = win.matchMedia(`(resolution: ${win.devicePixelRatio}dppx)`);
      ratioQuery.addEventListener('change', onRatio);
    };
    arm();
    undo.push(() => ratioQuery?.removeEventListener('change', onRatio));
    const motion = win.matchMedia('(prefers-reduced-motion: reduce)');
    const onMotion = (): void => { if (!stopped) handlers.motion(); };
    motion.addEventListener('change', onMotion);
    undo.push(() => motion.removeEventListener('change', onMotion));
    const fonts = win.document.fonts as FontFaceSet | undefined;
    // A load that brought no font faces changed nothing: Firefox fires an empty 'loadingdone' some 100 ms after
    // the page loads, and taking it for a font change ran layout again at the same sizes (spec L3; engines
    // report 2, item 2).
    const onFonts = (event: Event): void => {
      const faces = (event as Event & { fontfaces?: ArrayLike<unknown> }).fontfaces;
      if (stopped || (faces !== undefined && faces.length === 0)) return;
      handlers.fonts();
    };
    fonts?.addEventListener('loadingdone', onFonts);
    undo.push(() => fonts?.removeEventListener('loadingdone', onFonts));
  } catch (error) {
    stop();
    throw error;
  }
  return stop;
}

/**
 * Calls `onChange` when a `lang` attribute changes on `element` or an ancestor: the page's language decides
 * the formatting locale and which built-in text is marked English (spec A10, F6). An environment change,
 * kept apart from the theme watcher. Returns `stop`.
 */
export function watchLanguage(element: Element, onChange: () => void): () => void {
  const win = element.ownerDocument.defaultView;
  if (win === null) return () => {};
  const observer = new win.MutationObserver(records => {
    for (const r of records) {
      if (r.target instanceof win.Node && r.target.contains(element)) { onChange(); return; }
    }
  });
  observer.observe(element.ownerDocument.documentElement, { attributes: true, attributeFilter: ['lang'], subtree: true });
  return () => observer.disconnect();
}

/**
 * Theme resolution (spec L4, DX6, A5): decides light or dark for a chart root, and turns paints into both
 * CSS expressions (for the SVG renderer, which stays live) and concrete colors (for contrast checks). Concrete colors come from the browser itself through probe elements, never from parsing CSS.
 *
 * The chart paints no background unless the author sets `--axylo-background`: marks sit on whatever is
 * behind the chart. So the background used for checks is the effective opaque backdrop, found by walking up
 * from the chart and compositing computed background colors; with `--axylo-background` it is that color
 * (composited over the backdrop), which SVG then also paints. What is measured is what is drawn.
 */
import type { PaintBindings, PaintToken, ResolvedTheme } from '../core/contracts';
import { composite, isLightColor, parseColor, type Rgba } from './color';
import { LIGHT, SERIES_COUNT } from './palette';

export interface ThemeResolution {
  readonly bindings: PaintBindings;
  readonly theme: ResolvedTheme;
  /**
   * false when the element is not connected to a document: nothing could be computed, the paints are the
   * light defaults, and the caller should resolve again once the chart is attached.
   */
  readonly resolved?: boolean;
  /**
   * false when the backdrop behind the chart could not be determined (a background image on the way up):
   * `theme.paints.tokens.background` is then a guess, and the caller should skip the AX141 check.
   */
  readonly backdropKnown?: boolean;
  /** Series keys whose author color the browser does not accept as a color; they use their palette slot. */
  readonly invalidColors?: readonly string[];
}

const TOKENS: readonly PaintToken[] = ['axis', 'grid', 'reference', 'muted', 'focus', 'background', 'text'];

/**
 * CSS expressions for the token paints. Each public name (which an author may set anywhere, including
 * `:root`) falls back to a private default from the stylesheet.
 */
// Readonly by type; not frozen at run time, since a call at import time keeps a bundler from dropping the module.
export const TOKEN_BINDINGS: Readonly<Record<PaintToken, string>> = {
  axis: 'var(--axylo-axis, var(--axylo-default-axis))',
  grid: 'var(--axylo-grid, var(--axylo-default-grid))',
  reference: 'var(--axylo-reference, var(--axylo-default-reference))',
  muted: 'var(--axylo-muted, var(--axylo-default-muted))',
  focus: 'var(--axylo-focus, var(--axylo-default-focus))',
  // The author's background if any; else the backdrop resolveTheme found (set on the chart root).
  background: 'var(--axylo-background, var(--axylo-backdrop, var(--axylo-default-background)))',
  // The chart inherits the page's text color unless the author sets --axylo-text (spec DX6).
  text: 'var(--axylo-text, currentColor)',
};

/** The palette slot for a series index, as a CSS expression. */
export const seriesBinding = (index: number): string => {
  const n = (index % SERIES_COUNT) + 1;
  return `var(--axylo-series-${n}, var(--axylo-default-series-${n}))`;
};

/**
 * Name of the custom property, set on the chart root, that carries series `index`'s color. Marks reference
 * it rather than the color itself, so the color can change (an author's `var(--brand)`, forced colors on or
 * off) with no draw call.
 */
export const seriesProperty = (index: number): string => `--axylo-series-color-${index + 1}`;

/**
 * An author color as the value of its series property. `--axylo-forced-series` is unset except under forced
 * colors, where the stylesheet sets it to a system color: the author's color then steps aside, and comes back
 * when forced colors ends, with no draw call (review finding 6).
 */
const authorBinding = (expression: string): string => `var(--axylo-forced-series, ${expression})`;

/** Series property counts already written per root, so stale ones are removed when series go away. */
const written = new WeakMap<Element, number>();

/**
 * Resolves the theme for `element` (the chart root, normally `.axylo`), sets `data-axylo-scheme` on it,
 * and writes one `--axylo-series-color-N` property per series on it. `colors` maps series keys to the
 * author's CSS colors; they stay live (`var(--brand-1)` follows `--brand-1`), but a value the browser does
 * not accept as a color is replaced by the palette slot and listed in `invalidColors`.
 */
export function resolveTheme(
  element: HTMLElement,
  seriesKeys: readonly string[],
  colors?: Readonly<Record<string, string>> | null,
): ThemeResolution {
  const doc = element.ownerDocument;
  const win = doc.defaultView;
  const bindings: PaintBindings = { tokens: TOKEN_BINDINGS, series: seriesKeys.map((_, i) => `var(${seriesProperty(i)})`) };
  const authored = seriesKeys.map(key => {
    const own = colors != null && Object.prototype.hasOwnProperty.call(colors, key) ? colors[key] : undefined;
    return own !== undefined && own.trim() !== '' ? own.trim() : null;
  });

  if (win === null || !element.isConnected) {
    writeSeries(element, authored.map((own, i) => (own === null ? seriesBinding(i) : authorBinding(own))));
    return unresolved(element, bindings, seriesKeys.length);
  }

  const forcedColors = win.matchMedia('(forced-colors: active)').matches;
  const moreContrast = win.matchMedia('(prefers-contrast: more)').matches;

  const valid = validColors(element, authored);
  const invalidColors: string[] = [];
  writeSeries(element, authored.map((own, i) => {
    if (own === null) return seriesBinding(i);
    if (valid[i]) return authorBinding(own);
    invalidColors.push(seriesKeys[i]!);
    return seriesBinding(i);
  }));

  const backdrop = findBackdrop(element, win);
  setProperty(element, '--axylo-backdrop', rgbText(backdrop.color));

  const style = win.getComputedStyle(element);
  const override = style.getPropertyValue('--axylo-background').trim() !== '';
  const [overrideText, canvasText] = override ? probeColors(element, ['var(--axylo-background)', 'Canvas']) : [];
  const overrideColor = override ? parseColor(overrideText!) : null;
  const background = overrideColor !== null && overrideColor.a > 0 ? composite(overrideColor, backdrop.color) : backdrop.color;

  const overridden = overrideColor !== null && overrideColor.a > 0;
  const scheme = decideScheme(style, overridden ? background : null, element, canvasText);
  // Where the page sets the chart's color-scheme, the stylesheet's defaults follow the browser's used scheme
  // by themselves (light-dark()), media changes included, in the frame they happen: no attribute freezes one.
  // Otherwise (color-scheme normal, or the author's --axylo-background decides) the scheme found here is it.
  const follows = !overridden && style.colorScheme.trim() !== '' && style.colorScheme.trim() !== 'normal';
  if (follows) {
    if (element.hasAttribute('data-axylo-scheme')) element.removeAttribute('data-axylo-scheme');
  } else if (element.getAttribute('data-axylo-scheme') !== scheme) element.setAttribute('data-axylo-scheme', scheme);

  const expressions = [...TOKENS.map(t => TOKEN_BINDINGS[t]), ...bindings.series];
  const computed = probeColors(element, expressions);
  const tokens = {} as Record<PaintToken, string>;
  TOKENS.forEach((t, i) => { tokens[t] = computed[i]!; });
  // What is behind the marks, opaque: the author's background over the backdrop, or the backdrop.
  tokens.background = rgbText(background);
  const paints: PaintBindings = { tokens, series: computed.slice(TOKENS.length) };

  return {
    bindings,
    theme: { scheme, forcedColors, moreContrast, paints },
    resolved: true,
    backdropKnown: backdrop.known,
    invalidColors,
  };
}

function unresolved(element: HTMLElement, bindings: PaintBindings, count: number): ThemeResolution {
  const hex = (h: string): string => rgbText(parseColor(h)!);
  const tokens: Record<PaintToken, string> = {
    axis: hex(LIGHT.axis), grid: hex(LIGHT.grid), reference: hex(LIGHT.reference), muted: hex(LIGHT.muted),
    focus: hex(LIGHT.focus), background: hex(LIGHT.background), text: 'rgb(0, 0, 0)',
  };
  const series = Array.from({ length: count }, (_, i) => hex(LIGHT.series[i % SERIES_COUNT]!));
  const scheme = element.getAttribute('data-axylo-scheme') === 'dark' ? 'dark' : 'light';
  return {
    bindings,
    theme: { scheme, forcedColors: false, moreContrast: false, paints: { tokens, series } },
    resolved: false,
    backdropKnown: false,
    invalidColors: [],
  };
}

/**
 * Spec L4: `--axylo-background` decides if present (composited over the backdrop); else a computed
 * `color-scheme` naming exactly one of light and dark; else, for a list such as "light dark", the scheme
 * the browser actually uses there (the luminance of the `Canvas` system color in the chart's context);
 * else (unset or normal) the inherited text color: light text means a dark scheme.
 */
function decideScheme(style: CSSStyleDeclaration, background: Rgba | null, element: HTMLElement, canvas?: string): 'light' | 'dark' {
  if (background !== null) return isLightColor(background) ? 'light' : 'dark';
  const words = style.colorScheme.split(/\s+/).filter(w => w === 'light' || w === 'dark');
  const light = words.includes('light');
  const dark = words.includes('dark');
  if (light !== dark) return light ? 'light' : 'dark';
  if (light && dark) {
    const used = parseColor(canvas ?? probeColors(element, ['Canvas'])[0]!);
    if (used !== null) return isLightColor(used) ? 'light' : 'dark';
  }
  const text = parseColor(normalizeColor(style.color, element.ownerDocument));
  return text !== null && isLightColor(text) ? 'dark' : 'light';
}

interface Backdrop { readonly color: Rgba; readonly known: boolean }

/**
 * The opaque color behind the chart: computed background colors from the chart up, composited until one
 * is opaque, over the document's canvas color. A background image on the way up makes it unknown.
 */
function findBackdrop(element: HTMLElement, win: Window): Backdrop {
  const layers: Rgba[] = [];
  let known = true;
  let opaque = false;
  for (let node: Element | null = element; node !== null; node = parentOf(node)) {
    const cs = win.getComputedStyle(node);
    if (cs.backgroundImage !== 'none' && cs.backgroundImage !== '') { known = false; }
    const c = parseColor(normalizeColor(cs.backgroundColor, element.ownerDocument));
    if (c !== null && c.a > 0) {
      layers.push(c);
      if (c.a >= 1) { opaque = true; break; }
    }
  }
  let color: Rgba;
  if (opaque) color = layers.pop()!;
  else {
    // The page canvas: the `Canvas` system color under the root's color-scheme.
    const [canvas] = probeColors(element.ownerDocument.documentElement, ['Canvas']);
    color = parseColor(canvas!) ?? { r: 1, g: 1, b: 1, a: 1 };
    if (color.a < 1) color = composite(color, { r: 1, g: 1, b: 1, a: 1 });
  }
  while (layers.length > 0) color = composite(layers.pop()!, color);
  return { color, known };
}

/** Parent element, crossing out of a shadow root to its host. */
function parentOf(node: Element): Element | null {
  if (node.parentElement !== null) return node.parentElement;
  const root = node.parentNode;
  return root !== null && 'host' in root ? (root as ShadowRoot).host : null;
}

const rgbText = (c: Rgba): string => `rgb(${Math.round(c.r * 255)}, ${Math.round(c.g * 255)}, ${Math.round(c.b * 255)})`;

function setProperty(element: HTMLElement, name: string, value: string): void {
  if (element.style.getPropertyValue(name) !== value) element.style.setProperty(name, value);
}

function writeSeries(element: HTMLElement, values: readonly string[]): void {
  values.forEach((v, i) => setProperty(element, seriesProperty(i), v));
  const before = written.get(element) ?? 0;
  for (let i = values.length; i < before; i++) element.style.removeProperty(seriesProperty(i));
  written.set(element, values.length);
}

/**
 * Which author expressions the browser accepts as colors. Each is set as `color` on two probes whose parents
 * have different colors: an expression that is not a color is dropped at computed-value time, so `color`
 * inherits and the two probes disagree. Works for `var()` references too, which CSS.supports cannot judge.
 */
function validColors(element: HTMLElement, expressions: readonly (string | null)[]): boolean[] {
  if (!expressions.some(e => e !== null)) return expressions.map(() => true);
  const doc = element.ownerDocument;
  const win = doc.defaultView!;
  const box = doc.createElement('div');
  box.style.setProperty('display', 'none');
  const pairs = expressions.map(expression => {
    if (expression === null) return null;
    return (['rgb(1, 2, 3)', 'rgb(4, 5, 6)'] as const).map(parentColor => {
      const parent = doc.createElement('div');
      parent.style.setProperty('color', parentColor);
      parent.style.setProperty('forced-color-adjust', 'none');
      const probe = doc.createElement('span');
      probe.style.setProperty('forced-color-adjust', 'none');
      probe.style.setProperty('color', expression);
      parent.appendChild(probe);
      box.appendChild(parent);
      return probe;
    });
  });
  element.appendChild(box);
  const result = pairs.map((pair, i) => {
    if (pair === null) return true;
/**
 * Notices the page changes that can change a chart's theme (spec L4): the three media features, and the
 * `class`, `style` or `data-theme` attribute of the chart or any of its ancestors (a class-toggled dark
 * theme may sit on `<html>`, `<body>` or a card in between). Bursts are folded into one call.
 *
 * One MutationObserver covers the whole document (`subtree`), and a record counts only when its target is
 * the chart or one of its ancestors at that moment, so the watch keeps working when the chart is moved to
 * another parent or `<body>` is replaced. Inside a shadow root, that root is observed as well.
 */

const QUERIES = ['(prefers-color-scheme: dark)', '(forced-colors: active)', '(prefers-contrast: more)'];
const ATTRIBUTES = ['class', 'style', 'data-theme'];

/** Declarations resolveTheme itself writes on the chart root; changes to them alone are not theme changes. */
const OWN = /--axylo-(?:series-color-\d+|backdrop)\s*:[^;]*;?\s*/g;

/**
 * Calls `onChange` for a burst of relevant changes (once per observer batch), so the caller can feed it to its own
 * frame scheduler: the repaint lands in the next animation frame with any other pending work, drawn once
 * (review 3, finding 19). Returns `stop`.
 */
export function watchTheme(element: Element, onChange: () => void): () => void {
  const doc = element.ownerDocument;
  const win = doc.defaultView;
  if (win === null) return () => {};
  let stopped = false;

  // At once: the observer already delivers a burst as one batch, and the caller only marks itself dirty and
  // schedules its frame, so the repaint is in the very next animation frame.
  const schedule = (): void => {
    if (!stopped) onChange();
  };

  // Every subscription's release is kept as it is made, so a failure part-way (an observe() that throws)
  // leaves nothing registered (final review, finding 14).
  const undo: (() => void)[] = [];
  const release = (): void => {
    stopped = true;
    for (let fn = undo.pop(); fn; fn = undo.pop()) {
      try { fn(); } catch { /* keep releasing */ }
    }
  };
  try {
    for (const q of QUERIES) {
      const list = win.matchMedia(q);
      list.addEventListener('change', schedule);
      undo.push(() => list.removeEventListener('change', schedule));
    }
    const observer = new win.MutationObserver(records => {
      for (const r of records) {
        if (!holds(r.target, element)) continue;
        if (r.target === element && r.attributeName === 'style') {
          const before = (r.oldValue ?? '').replace(OWN, '').trim();
          const after = (element.getAttribute('style') ?? '').replace(OWN, '').trim();
          if (before === after) continue;
        }
        schedule();
        return;
      }
    });
    undo.push(() => observer.disconnect());
    const options: MutationObserverInit = { attributes: true, attributeFilter: ATTRIBUTES, attributeOldValue: true, subtree: true };
    observer.observe(doc.documentElement, options);
    const root = element.getRootNode();
    if (root !== doc && 'host' in root) observer.observe(root, options);
  } catch (error) {
    release();
    throw error;
  }

  return () => {
    if (stopped) return;
    release();
  };
}

/** True when `target` is `element` or one of its ancestors, crossing shadow roots to their hosts. */
function holds(target: Node, element: Node): boolean {
  for (let n: Node | null = element; n !== null; n = n.parentNode ?? ('host' in n ? (n as ShadowRoot).host : null)) {
    if (n === target) return true;
  }
  return false;
}
/**
 * The library's default stylesheet as a string. `ensureStyles` adopts it as a constructable stylesheet; the
 * build writes the same string to dist/axylo.css for pages that prefer to load it themselves.
 *
 * Everything sits in the `axylo` cascade layer so that any unlayered rule of the page wins over a default
 * without a specificity contest, whichever order the sheets arrive in.
 *
 * Token scheme: the sheet sets only private defaults (`--axylo-default-axis`, `--axylo-default-series-1`, …)
 * on `.axylo`. The public names (`--axylo-axis`, `--axylo-series-1`, `--axylo-background`, `--axylo-text`,
 * `--axylo-font-family`, …) are never set outside forced colors, so an author may set them anywhere,
 * including `:root`, and inheritance carries them in. Every use reads `var(--axylo-x, var(--axylo-default-x))`.
 *
 * Things this sheet must never do, because scheme detection (spec L4) reads them from the chart root: set
 * `color-scheme` or `color` on `.axylo`, or set `--axylo-background` outside forced colors.
 *
 * Component selectors are scoped beneath `.axylo`, so a page's own `.axylo-text` is left alone.
 */
import { DARK, LIGHT, type SchemeColors } from './palette';

/** Each default as `light-dark(light, dark)`: the browser picks by the chart's used colour scheme. */
function following(light: SchemeColors, dark: SchemeColors): string {
  const pair = (a: string, b: string) => `light-dark(${a}, ${b})`;
  const series = light.series.map((v, i) => `    --axylo-default-series-${i + 1}: ${pair(v, dark.series[i]!)};`).join('\n');
  return `${series}
    --axylo-default-background: ${pair(light.background, dark.background)};
    --axylo-default-axis: ${pair(light.axis, dark.axis)};
    --axylo-default-grid: ${pair(light.grid, dark.grid)};
    --axylo-default-muted: ${pair(light.muted, dark.muted)};
    --axylo-default-reference: ${pair(light.reference, dark.reference)};
    --axylo-default-focus: ${pair(light.focus, dark.focus)};`;
}

function tokens(c: SchemeColors): string {
  const series = c.series.map((v, i) => `    --axylo-default-series-${i + 1}: ${v};`).join('\n');
  return `${series}
    --axylo-default-background: ${c.background};
    --axylo-default-axis: ${c.axis};
    --axylo-default-grid: ${c.grid};
    --axylo-default-muted: ${c.muted};
    --axylo-default-reference: ${c.reference};
    --axylo-default-focus: ${c.focus};`;
}

// Forced colors: every paint becomes a system color. `!important` so an author's custom property, whether
// inherited or set on the chart, cannot leak a brand color into a mode where the user chose the colors.
// `--axylo-forced-series` switches off the author's pinned series colors (resolveTheme writes each as
// `var(--axylo-forced-series, <author color>)` on the chart root), so they return when forced colors ends.
const forced = [
  ...LIGHT.series.map((_, i) => `    --axylo-series-${i + 1}: CanvasText !important;`),
  '    --axylo-forced-series: CanvasText !important;',
  '    --axylo-background: Canvas !important;',
  '    --axylo-default-background: Canvas !important;',
  '    --axylo-text: CanvasText !important;',
  '    --axylo-axis: CanvasText !important;',
  '    --axylo-grid: GrayText !important;',
  '    --axylo-muted: GrayText !important;',
