/**
 * Shared setup for browser tests: a static server over the repository and one browser instance.
 * Tests load test/browser/page.html, which pulls in the built script-tag bundle, and drive it with Playwright.
 *
 * The engine is chosen with AXYLO_ENGINE: `chromium` (the default: system Chrome, `channel: 'chrome'`, exactly
 * as before), `firefox` or `webkit` (Playwright's own builds). Every test's Vitest metadata carries the engine
 * and its version (`meta.engine`, `meta.engineVersion`, in the JSON report's assertion results), so results
 * from different engines cannot be confused. A test that needs something only one engine offers calls
 * `requireEngineFeature`, which reports it as not run on the others, with the reason (`meta.notRun`).
 */
import { chromium, firefox, webkit, type Browser, type BrowserContext, type BrowserContextOptions, type Page } from 'playwright-core';
import { afterEach, beforeEach, TestRunner } from 'vitest';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '../../../..');
const types: Record<string, string> = { '.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.png': 'image/png', '.woff2': 'font/woff2' };

let server: http.Server | undefined;
let browser: Browser | undefined;
let base = '';

export type Engine = 'chromium' | 'firefox' | 'webkit';
const requested = process.env.AXYLO_ENGINE ?? 'chromium';
if (requested !== 'chromium' && requested !== 'firefox' && requested !== 'webkit') throw new Error(`AXYLO_ENGINE must be chromium, firefox or webkit, not ${requested}`);
export const ENGINE: Engine = requested;

/** The version of the running browser, once started. */
export const engineVersion = (): string => browser?.version() ?? '';

// Every test records the engine it ran on. Registered when a test file imports the harness.
beforeEach(context => {
  Object.assign(context.task.meta, { engine: ENGINE, engineVersion: engineVersion() });
});

// The contexts each test opened. A test reported as not run stops where it is, before it closes its pages:
// they are closed after it, or dozens pile up until the file's last hook and make it time out. Only tests
// that call requireEngineFeature off its engines are affected; a Chrome run never reaches this.
const opened = new Map<string, BrowserContext[]>();
function track(context: BrowserContext): void {
  const id = TestRunner.getCurrentTest()?.id;
  if (id === undefined) return;
  const list = opened.get(id) ?? [];
  list.push(context);
  opened.set(id, list);
}
afterEach(async context => {
  const list = opened.get(context.task.id) ?? [];
  opened.delete(context.task.id);
  if ((context.task.meta as { notRun?: string }).notRun === undefined) return;
  await Promise.all(list.map(c => c.close().catch(() => undefined)));
});

/**
 * Reports the current test as not run on this engine, with `reason`, unless the engine is one of `engines`:
 * for evidence only those engines can give (Chrome's DevTools protocol: its computed accessibility tree,
 * touch input beyond a tap). Never a silent pass: Vitest records the test as skipped and `meta.notRun`
 * carries the reason.
 */
export function requireEngineFeature(engines: readonly Engine[], reason: string): void {
  if (engines.includes(ENGINE)) return;
  const test = TestRunner.getCurrentTest();
  if (!test) throw new Error(`not available on ${ENGINE}: ${reason}`);
  Object.assign(test.meta, { engine: ENGINE, engineVersion: engineVersion(), notRun: `${ENGINE}: ${reason}` });
  test.context.skip(`not run on ${ENGINE}: ${reason}`);
}

export async function start(): Promise<void> {
  server = http.createServer((req, res) => {
    const file = path.join(root, decodeURIComponent(new URL(req.url ?? '/', 'http://x').pathname));
    if (!file.startsWith(root) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404).end(); return; }
    res.writeHead(200, { 'content-type': types[path.extname(file)] ?? 'application/octet-stream' }).end(fs.readFileSync(file));
  });
  await new Promise<void>(r => server!.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${(server.address() as { port: number }).port}`;
  browser = ENGINE === 'chromium' ? await chromium.launch({ channel: 'chrome', headless: true })
    // Firefox applies Ctrl + wheel as page zoom (the browser's default, which I3 requires the chart to leave alone)
    // and by default remembers it per site in the shared profile, so it would leak into every later context on
    // this origin. Per-tab zoom keeps each test's page at 100 %.
    : ENGINE === 'firefox' ? await firefox.launch({ headless: true, firefoxUserPrefs: { 'browser.zoom.siteSpecific': false } })
    : await webkit.launch({ headless: true });
}

export async function stop(): Promise<void> {
  await browser?.close();
  await new Promise<void>(r => server ? server.close(() => r()) : r());
}

/** Opens the blank test page with the Axylo script-tag bundle loaded as `window.Axylo`. */
export async function openPage(options: BrowserContextOptions & { query?: string } = {}): Promise<Page> {
  const { query = '', ...ctx } = options;
  const context = await browser!.newContext({ viewport: { width: 900, height: 700 }, locale: 'en-US', timezoneId: 'UTC', ...ctx });
  track(context);
  const page = await context.newPage();
  const errors: string[] = [];
  page.on('pageerror', e => errors.push(String(e)));
  (page as Page & { errors: string[] }).errors = errors;
  await page.goto(`${base}/packages/axylo/test/browser/page.html${query}`);
  return page;
}

export const url = (p: string): string => `${base}/${p}`;

/**
 * Bundles a TypeScript entry for the browser and opens a page that has run it. The entry talks to the test
 * through globals it sets on `window`. Use this to test a module in a real browser before the public bundle
 * exposes it.
 */
export async function openEntry(entry: string, options: BrowserContextOptions & { query?: string; html?: string } = {}): Promise<Page> {
  const { build } = await import('esbuild');
  const out = path.join(root, 'packages/axylo/test/browser/.out', path.basename(entry).replace(/\.tsx?$/, '.js'));
  await build({ entryPoints: [path.resolve(root, entry)], bundle: true, format: 'iife', target: 'es2022', define: { __DEV__: 'true' }, outfile: out, logLevel: 'silent' });
  const { query = '', html, ...ctx } = options;
  const context = await browser!.newContext({ viewport: { width: 900, height: 700 }, locale: 'en-US', timezoneId: 'UTC', ...ctx });
  track(context);
  const page = await context.newPage();
  const errors: string[] = [];
  page.on('pageerror', e => errors.push(String(e)));
  (page as Page & { errors: string[] }).errors = errors;
  await page.goto(`${base}/packages/axylo/test/browser/${html ?? 'blank.html'}${query}`);
  await page.addScriptTag({ url: `${base}/${path.relative(root, out)}` });
  return page;
}
// Builds packages/axylo/dist: ESM (production and development flavours), script-tag files, CSS and type declarations.
//
// Importing this file builds nothing: it exports what another build of the library from source needs to
// reproduce these files (bench/build.mjs): `stylesheets()` and `stylesheetPlugin(text)`, and the `define`
// objects. Run directly (`node scripts/build.mjs`, `npm run build`), it builds.
import { build } from 'esbuild';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const pkg = path.join(root, 'packages/axylo');

/** Runs a source module through esbuild and imports it, for the values the build needs from the library. */
async function evaluate(entry) {
  const r = await build({ entryPoints: [entry], bundle: true, format: 'esm', write: false, logLevel: 'silent' });
  return import('data:text/javascript;base64,' + Buffer.from(r.outputFiles[0].contents).toString('base64'));
}

/**
 * The stylesheet's source of truth is src/theme/css.ts, a string in the library (it is also applied at run time
 * without a <style> element). The production files get it minified (src/theme/minify.ts: comments and layout
 * whitespace only) as a literal, so they do no work at import time, and dist/axylo.css is that same text. The
 * development files keep css.ts as written, so they stay what a plain build of the source gives.
 */
export async function stylesheets() {
  const { AXYLO_CSS: readable } = await evaluate(path.join(pkg, 'src/theme/css.ts'));
  const { minifyCss } = await evaluate(path.join(pkg, 'src/theme/minify.ts'));
  return { readable, minified: minifyCss(readable) };
}

/** Replaces src/theme/css.ts with the given stylesheet text as a literal. */
export function stylesheetPlugin(text) {
  const module = path.join(pkg, 'src/theme/css.ts');
  return {
    name: 'axylo-stylesheet',
    setup(b) {
      b.onLoad({ filter: /[\\/]theme[\\/]css\.ts$/ }, args => path.resolve(args.path) === module
        ? { contents: `export const AXYLO_CSS = ${JSON.stringify(text)};`, loader: 'js' } : undefined);
    },
  };
}

/**
 * Build-time constants. __BENCH__ carries the benchmark instrumentation (src/core/instrument.ts): false in every
 * shipped file (the development files have it through __DEV__); a benchmark build sets it true.
 */
export const PRODUCTION = { __DEV__: 'false', __BENCH__: 'false' };
export const DEVELOPMENT = { __DEV__: 'true', __BENCH__: 'false' };

async function main() {
  const dist = path.join(pkg, 'dist');
  fs.rmSync(dist, { recursive: true, force: true });
  const { minified } = await stylesheets();
  const common = { entryPoints: [path.join(pkg, 'src/index.ts')], bundle: true, target: 'es2022', legalComments: 'none', logLevel: 'warning', absWorkingDir: root };
  const prod = { define: PRODUCTION, plugins: [stylesheetPlugin(minified)] };
  const dev = { define: DEVELOPMENT };
  await Promise.all([
    build({ ...common, ...prod, format: 'esm', minify: true, outfile: path.join(dist, 'axylo.js') }),
    build({ ...common, ...dev, format: 'esm', outfile: path.join(dist, 'axylo.dev.js') }),
    build({ ...common, ...dev, format: 'iife', globalName: 'Axylo', outfile: path.join(dist, 'axylo.iife.js') }),
    build({ ...common, ...prod, format: 'iife', globalName: 'Axylo', minify: true, outfile: path.join(dist, 'axylo.iife.min.js') }),
  ]);
  // For pages that prefer to load the stylesheet themselves, for example under a strict Content Security Policy.
  fs.writeFileSync(path.join(dist, 'axylo.css'), minified);
  execFileSync('npx', ['tsc', '-p', path.join(pkg, 'tsconfig.build.json')], { stdio: 'inherit', cwd: root });
  console.log('built', fs.readdirSync(dist).filter(f => !fs.statSync(path.join(dist, f)).isDirectory()).join(', '));
}

if (path.resolve(process.argv[1] ?? '') === import.meta.filename) await main();
/**
 * Applies the default stylesheet (plan 2.4) to the root a chart lives in: its document, or the shadow root
 * that contains it (a document's sheets do not reach into a shadow tree).
 *
 * - Normally a constructable stylesheet is adopted (`adoptedStyleSheets`); no `<style>` element is created.
 * - A root that already has the standalone dist/axylo.css active gets nothing. "Active" is checked by its
 *   effect (a probe element picks up the sheet's own rules), not by trusting a sentinel property, and is
 *   checked again on later calls, so a sheet that was removed or disabled is replaced.
 * - Only where constructable or adopted stylesheets are missing is one `<style>` element inserted instead.
 *   This is the only case in which the library creates a style element.
 */
import { AXYLO_CSS } from './css';

type StyleRoot = Document | ShadowRoot;

type Installed =
  | { readonly kind: 'adopted'; readonly sheet: CSSStyleSheet }
  | { readonly kind: 'element'; readonly element: HTMLStyleElement }
  | { readonly kind: 'standalone'; readonly sheet: CSSStyleSheet | null };

const installed = new WeakMap<StyleRoot, Installed>();
/** One constructed sheet per document, shared by its document and shadow roots. */
const constructed = new WeakMap<Document, CSSStyleSheet>();

/**
 * Makes the default styles apply to `root` (a Document or a ShadowRoot). Safe to call any number of times;
 * after the first call it costs a few property reads unless the sheet it relied on has gone away.
 */
export function ensureStyles(root: StyleRoot): void {
  const state = installed.get(root);
  if (state !== undefined && stillActive(root, state)) return;
  const doc = 'ownerDocument' in root && root.ownerDocument !== null ? root.ownerDocument : (root as Document);
  const win = doc.defaultView;
  if (win === null) return;

  const standalone = findStandalone(root, doc, win);
  if (standalone !== undefined) { installed.set(root, { kind: 'standalone', sheet: standalone }); return; }

  if (canAdopt(root, win)) {
    let sheet = constructed.get(doc);
    if (sheet === undefined) {
      // The constructor must come from the document's own window, or adopting the sheet throws.
      sheet = new win.CSSStyleSheet();
      sheet.replaceSync(AXYLO_CSS);
      constructed.set(doc, sheet);
    }
    const list = (root as { adoptedStyleSheets: CSSStyleSheet[] }).adoptedStyleSheets;
    if (!list.includes(sheet)) (root as { adoptedStyleSheets: CSSStyleSheet[] }).adoptedStyleSheets = [...list, sheet];
    installed.set(root, { kind: 'adopted', sheet });
    return;
  }

  const element = doc.createElement('style');
  element.setAttribute('data-axylo-styles', '');
  element.textContent = AXYLO_CSS;
  if (root === doc) (doc.head ?? doc.documentElement).appendChild(element);
  else root.insertBefore(element, root.firstChild);
  installed.set(root, { kind: 'element', element });
}

function stillActive(root: StyleRoot, state: Installed): boolean {
  switch (state.kind) {
    case 'adopted': return (root as { adoptedStyleSheets?: CSSStyleSheet[] }).adoptedStyleSheets?.includes(state.sheet) ?? false;
    case 'element': return state.element.isConnected && state.element.sheet !== null && !state.element.sheet.disabled;
    case 'standalone': {
      if (state.sheet === null) return false; // not identifiable: verify by effect again
      const owner = state.sheet.ownerNode;
      return !state.sheet.disabled && owner !== null && owner.isConnected && Array.prototype.includes.call(root.styleSheets, state.sheet);
    }
  }
}

function canAdopt(root: StyleRoot, win: Window): boolean {
  if (!('adoptedStyleSheets' in root)) return false;
  const Sheet = (win as unknown as { CSSStyleSheet?: { new(): CSSStyleSheet; prototype: Partial<CSSStyleSheet> } }).CSSStyleSheet;
  if (typeof Sheet !== 'function' || typeof Sheet.prototype.replaceSync !== 'function') return false;
  try { new Sheet(); } catch { return false; }
  return true;
}

/**
 * The standalone sheet if it is in effect in `root`: undefined if not, null if in effect but not
 * identifiable (a cross-origin sheet whose rules cannot be read). In effect means a probe chart root picks
 * up a private token and a mark rule that only this stylesheet defines; custom properties alone could be
 * inherited from outside a shadow root, so a non-inherited property is checked as well.
 */
function findStandalone(root: StyleRoot, doc: Document, win: Window): CSSStyleSheet | null | undefined {
  const probe = doc.createElement('div');
  probe.className = 'axylo';
  probe.style.setProperty('display', 'none');
  const mark = doc.createElement('div');
  mark.className = 'axylo-svg';
  probe.appendChild(mark);
  (root === doc ? doc.documentElement : root).appendChild(probe);
  const token = win.getComputedStyle(probe).getPropertyValue('--axylo-default-background').trim();
  const rule = win.getComputedStyle(mark).position;
  probe.remove();
  if (token === '' || rule !== 'absolute') return undefined;
  for (const sheet of Array.from(root.styleSheets)) {
    try {
      for (const r of Array.from(sheet.cssRules)) if (r.cssText.includes('--axylo-stylesheet')) return sheet;
    } catch {
      // Cross-origin: its rules cannot be read.
    }
  }
  return null;
}
